const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2023;
  const startDate = `${year}-01-01`;
  const endDate = `${year}-12-31`;
  const hectaresThreshold = 160000;

  // Get the geometry for Quebec, Canada.
  const quebec = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
    .filter(ee.Filter.eq('country_na', 'Canada'))
    .filter(ee.Filter.eq('name', 'Quebec'));

  if (quebec.size().getInfo() === 0) {
      console.log("Could not find geometry for Quebec.");
      console.log("D");
      return;
  }
  const geometry = quebec.geometry();

  // 2. Data Acquisition & Check
  // Use MODIS Thermal Anomalies/Fire locations. Each point represents a 1km pixel.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(geometry)
    .select('MaxFRP'); // Selecting a band is good practice, even if not used, to make collection lighter

  if (fireCollection.size().getInfo() === 0) {
    console.log(`No MODIS fire data found for Quebec in ${year}.`);
    console.log("C1");
    return;
  }

  // 3. Processing
  // Create an image where each pixel is 1 if a fire was detected, 0 otherwise.
  // This approach counts each 1km pixel only once, even if it burned on multiple days.
  // The 'MaxFRP' band exists for every fire detection, so we create a constant band and mosaic.
  const fireImage = fireCollection.map(function(img) {
      return ee.Image(1).reproject({crs: img.projection()});
    }).mosaic().clip(geometry);

  // 4. Calculation
  // Calculate the area by multiplying the count of fire pixels by the area of each pixel.
  // Each MODIS pixel is 1km x 1km = 100 hectares.
  // We use a reducer to sum the values of all pixels in the image.
  const scale = 1000; // Native resolution of MODIS fire product
  const firePixelCountResult = fireImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  });

  // Check for calculation failure.
  const firePixelCount = firePixelCountResult.get('constant');
  if (firePixelCount.getInfo() === null) {
      console.log("Failed to calculate fire pixel count.");
      console.log("C3");
      return;
  }

  const validPixelCount = firePixelCount.getInfo();
  if (validPixelCount === 0) {
    console.log("MODIS images were found, but no fire pixels were detected within Quebec in 2023.");
    console.log("B"); // It's a valid zero, so the answer is No.
    return;
  }

  const totalHectares = validPixelCount * 100; // Each 1km pixel is 100 hectares

  // 5. Validation & Final Answer
  console.log(`Year: ${year}`);
  console.log(`Detected Fire Pixels (1km): ${validPixelCount}`);
  console.log(`Estimated Burned Area (hectares): ${Math.round(totalHectares)}`);
  console.log(`Threshold (hectares): ${hectaresThreshold}`);

  if (totalHectares > hectaresThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
